<h2>Crear curso</h2><form method="post" action="index.php?route=course_save"><input type="hidden" name="operation" value="create"><div class="form-group"><label>Nombre del curso</label><input class="form-control" name="name" maxlength="150" value="<?=e($course['name']??'')?>" required></div>
<div class="form-group"><label>Código</label><input class="form-control" name="course_code" maxlength="30" value="<?=e($course['course_code']??'')?>" required></div>
<div class="form-group"><label>Carrera</label><select class="form-control" name="career_id" required><option value="">Seleccione</option><?php foreach($careers as $career): ?><option value="<?=(int)$career['id']?>" <?=isset($course)&&(int)$course['career_id']===(int)$career['id']?'selected':''?>><?=e($career['name'])?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>Créditos</label><input class="form-control" type="number" name="credits" min="0" max="255" value="<?=e($course['credits']??'')?>" required></div>
<div class="form-group"><label>Descripción</label><textarea class="form-control" name="description" required><?=e($course['description']??'')?></textarea></div><button class="btn btn-primary">Guardar</button> <a class="btn btn-secondary" href="index.php?route=courses">Cancelar</a></form>